        # Note: r=2 is impossible as q > 2. r must be odd.
        for r in range(q + 1, 800):
            if is_prime(r):
                # Calculate the four quantities
                A = p + q - r  # 800 - r
                B = q + r - p
                C = r + p - q
                D = p + q + r  # 800 + r

                # Check if all are prime
                if is_prime(A) and is_prime(B) and is_prime(C) and is_prime(D):
                    valid_r_primes.append(r)

        results_r[(p, q)] = valid_r_primes

    print("\n--- Results for r ---")
