def solve_case_2():
    MAX_SUM = 800

    # 1. Generate primes up to MAX_SUM
    primes = [i for i in range(2, MAX_SUM + 1) if is_prime(i)]
    prime_set = set(primes)

    valid_solutions = []
    max_r = 0

    # 2. Iterate through q, where q < r and q+r = 800
    for q in primes:
        if q >= MAX_SUM / 2:
            break

        r = MAX_SUM - q

        if r in prime_set and q < r:
            # (q, r) pair found

            # 3. Iterate through p, where p < q
            for p in primes:
                if p >= q:
                    break

                # 4. Check required condition: p + 2q > 800
                if p + 2 * q <= MAX_SUM:
                    continue

                # Now check the four required sums

                # S1 = p + q - r = p + 2q - 800
                S1 = p + 2 * q - MAX_SUM

                # S2 = q + r - p = 800 - p
                S2 = MAX_SUM - p

                # S3 = r + p - q = 800 + p - 2q
                S3 = MAX_SUM + p - 2 * q

                # S4 = p + q + r = p + 800
                S4 = p + MAX_SUM

                # Check primality of the four sums
                if is_prime(S1) and is_prime(S2) and is_prime(S3) and is_prime(S4):
                    valid_solutions.append((p, q, r))
                    if r > max_r:
                        max_r = r

    return valid_solutions, max_r

